// Container + Elemente erfassen
var conts=[];
function key(el,i){var h=el.querySelector('h1,h2,h3');var t=h?h.textContent.trim().replace(/\s+/g,' ').slice(0,40):'';return i+'|'+t;}
// Ebene "Bereiche": direkte Kinder von .main ausser Kopfzeile
var secs=[].filter.call(main.children,function(e){return !e.classList.contains('headbar')&&e.tagName!='SCRIPT';});
if(secs.length>1)conts.push({el:main,kind:'sec',items:secs});
// Ebene "Kacheln": Kinder von Grid-Containern
[].forEach.call(main.querySelectorAll(GRIDSEL),function(g){var it=[].filter.call(g.children,function(e){return e.tagName!='SCRIPT'&&e.tagName!='STYLE';});if(it.length>1)conts.push({el:g,kind:'it',items:it});});
if(!conts.length)return;
conts.forEach(function(c,ci){c.id=c.kind+ci;c.items.forEach(function(e,i){e.setAttribute('data-ua',(c.kind=='sec'?'s':'t')+key(e,i));e.classList.add(c.kind=='sec'?'ua-sec':'ua-it');
  if(getComputedStyle(e).position=='static')e.style.position='relative';
  var ctl=document.createElement('span');ctl.className='ua-ctl';
  ctl.innerHTML='<button class="hd" title="Ziehen">⠿</button><button data-a="-1" title="nach vorn">'+(c.kind=='sec'?'▲':'◀')+'</button><button data-a="1" title="nach hinten">'+(c.kind=='sec'?'▼':'▶')+'</button>'+(c.kind=='it'?'<button data-a="w" title="breit/schmal">⇔</button>':'');
  e.appendChild(ctl);});
  c.def=c.items.map(function(e){return e.getAttribute('data-ua');});});

function kids(c){return [].filter.call(c.el.children,function(e){return e.hasAttribute('data-ua')&&(c.kind=='sec'?e.classList.contains('ua-sec'):e.classList.contains('ua-it'));});}
function save(){var o={};conts.forEach(function(c){o[c.id]=kids(c).map(function(e){return {k:e.getAttribute('data-ua'),w:e.getAttribute('data-uaw')=='1'};});});try{localStorage.setItem(KEY,JSON.stringify(o));}catch(x){}}
function wide(e,on){if(on){e.setAttribute('data-uaw','1');e.style.gridColumn='1 / -1';}else{e.removeAttribute('data-uaw');e.style.gridColumn='auto';}}
function apply(o){conts.forEach(function(c){var l=o&&o[c.id];if(!Array.isArray(l))return;var cur=kids(c),map={};cur.forEach(function(e){map[e.getAttribute('data-ua')]=e;});
  var anchor=cur.length?cur[cur.length-1].nextSibling:null,seen={};
  l.forEach(function(x){var e=map[x.k];if(!e)return;seen[x.k]=1;c.el.insertBefore(e,anchor);if(c.kind=='it')wide(e,x.w);});
  cur.forEach(function(e){if(!seen[e.getAttribute('data-ua')])c.el.insertBefore(e,anchor);});});}
function load(){try{return JSON.parse(localStorage.getItem(KEY)||'null');}catch(x){return null;}}
function redraw(){setTimeout(function(){try{document.dispatchEvent(new Event('ftuiVisibilityChanged'));}catch(x){}window.dispatchEvent(new Event('resize'));},50);}
conts.forEach(function(c){if(c.kind=='it')c.items.forEach(function(e){var cs=getComputedStyle(e);if(cs.gridColumnStart=='1'&&cs.gridColumnEnd=='-1'){e.setAttribute('data-uaw0','1');e.setAttribute('data-uaw','1');}});});
apply(load());

// Knopf in Kopfzeile
var hb=main.querySelector('.headbar'),bt=document.createElement('button'),br=document.createElement('button');
bt.className='ua-btn';bt.textContent='⇅';bt.title='Kacheln anordnen';br.className='ua-btn ua-rst';br.textContent='Zurücksetzen';
var host=hb||main,clk=host.querySelector('.clock');host.insertBefore(br,clk||null);host.insertBefore(bt,clk||null);
